import {SPECIALTIES,DOCTORS,STATUS,clinicNow,addDays,weekday,minutes,timeString,duration,overlap,uid,seed,slots,saveAppointment,addBlock} from './model.js';

const KEY='integra-demo-v1', SESSION='integra-session-v1';
const app=document.querySelector('#app'), modal=document.querySelector('#modal');
const paths={
  plus:'M12 4v16M4 12h16',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',
  calendar:'M8 2v4m8-4v4M3 9h18M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2ZM7 13h2m4 0h2m-8 4h2m4 0h2',
  clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',user:'M20 21v-2a6 6 0 0 0-6-6h-4a6 6 0 0 0-6 6v2M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',
  users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.9M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm8 .2a4 4 0 0 1 0 7.6',
  heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',
  stethoscope:'M6 3v2m8-2v2M4 4v6a6 6 0 0 0 12 0V4M10 16v1a5 5 0 0 0 10 0v-3m2-3a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',
  spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Zm8-2v4m-2-2h4',
  brain:'M12 4a3 3 0 0 0-5-1 4 4 0 0 0-4 5 4 4 0 0 0-1 7 4 4 0 0 0 5 5 3 3 0 0 0 5 0V4Zm0 0a3 3 0 0 1 5-1 4 4 0 0 1 4 5 4 4 0 0 1 1 7 4 4 0 0 1-5 5 3 3 0 0 1-5 0M7 7l2 2m-5 5h3m10-7-2 2m5 5h-3',
  leaf:'M20 3S6 1 4 9s5 13 11 8 5-14 5-14ZM3 21l12-12',activity:'M2 12h5l3-9 4 18 3-9h5',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6l-9-4Zm-4 10 3 3 5-6',
  pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',grid:'M3 3h7v7H3V3Zm11 0h7v7h-7V3ZM3 14h7v7H3v-7Zm11 0h7v7h-7v-7Z',
  list:'M9 6h12M9 12h12M9 18h12M3 6h1m-1 6h1m-1 6h1',chart:'M4 3v18h18M8 16v-4m5 4V7m5 9V4',lock:'M5 10h14v11H5V10Zm3 0V6a4 4 0 0 1 8 0v4M12 14v3',
  logout:'M9 3H3v18h6m6-14 5 5-5 5M8 12h12',external:'M14 3h7v7m0-7L10 14M9 3H3v18h18v-6',download:'M12 3v12m-5-5 5 5 5-5M3 17v4h18v-4',menu:'M3 6h18M3 12h18M3 18h18',info:'M12 11v6m0-10v.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',mail:'M3 5h18v14H3V5Zm0 0 9 8 9-8',phone:'M7 3H3v4c0 7.7 6.3 14 14 14h4v-4l-5-2-2 2a12 12 0 0 1-7-7l2-2-2-5',settings:'M4 6h16M4 12h16M4 18h16M8 3v6m8 0v6m-6 0v6',back:'m14 5-7 7 7 7',refresh:'M20 7V2m0 5h-5m5 0a9 9 0 1 0 1 10'
};
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.plus}"/></svg>`;}
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const doctor=id=>DOCTORS.find(d=>d.id===id);
const specialty=id=>SPECIALTIES.find(s=>s.id===id);
const patient=id=>db.patients.find(p=>p.id===id);
const initials=name=>name.split(' ').map(s=>s[0]).filter(Boolean).slice(0,2).join('');
const fmt=(date,options={day:'2-digit',month:'short'})=>new Date(date+'T12:00:00').toLocaleDateString('pt-BR',options);
const stamp=value=>new Date(value).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});
const badge=status=>`<span class="status ${status}">${STATUS[status]}</span>`;
const avatar=(name,color='#edf2f8')=>`<span class="avatar" style="background:${color}">${e(initials(name))}</span>`;
const brand=()=>`<span class="brand"><span class="brand-symbol">${icon('plus')}</span><span class="brand-name">integra<small>Clínica multidisciplinar</small></span></span>`;
function readDb(){try{const value=JSON.parse(localStorage.getItem(KEY));if(value?.version===1&&Array.isArray(value.appointments)&&Array.isArray(value.patients)&&Array.isArray(value.blocks)&&value.hours)return value;}catch{}return seed();}
let db=readDb(),session=null,page='overview',selectedDate=clinicNow().date;
try{session=JSON.parse(sessionStorage.getItem(SESSION));if(!['admin','reception','doctor','patient'].includes(session?.role))session=null;}catch{}
let filters={search:'',status:'',doctor:'',date:''},reportStart=addDays(clinicNow().date,-30),reportEnd=addDays(clinicNow().date,90),booking=null,toastTimer;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(db));}catch{toast('O navegador não permitiu salvar os dados. Mantenha esta aba aberta.');}}
function saveSession(){if(session)sessionStorage.setItem(SESSION,JSON.stringify(session));else sessionStorage.removeItem(SESSION);}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
function openModal(html){modal.innerHTML=html;if(!modal.open)modal.showModal();}
function closeModal(){modal.close();booking=null;}
function modalHead(title,subtitle=''){return `<div class="modal-head"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-btn" data-action="close" aria-label="Fechar">${icon('close')}</button></div>`;}
function setRole(role,extra={}){session={role,...extra};page=role==='patient'?'appointments':'overview';filters={search:'',status:'',doctor:'',date:''};saveSession();closeModal();render();window.scrollTo(0,0);}
function allowedTeam(){return session&&['admin','reception'].includes(session.role);}
function visibleAppointments(){if(session?.role==='patient')return db.appointments.filter(a=>a.patientId===session.patientId);if(session?.role==='doctor')return db.appointments.filter(a=>a.doctorId===session.doctorId);return db.appointments;}
function render(){db=readDb();if(session?.role==='patient'&&!patient(session.patientId)){session=null;saveSession();}app.innerHTML=session?workspace():home();document.title=session?`${session.role==='patient'?'Área do paciente':'Painel da equipe'} | Clínica Integra`:'Clínica Integra — Clínica multidisciplinar · São Paulo';}

function home(){return `
  <div class="demo-bar"><div class="container"><span class="demo-label">Template demonstrativo · Clínica e dados fictícios</span><button data-action="roles">Explorar painéis ${icon('arrow')}</button></div></div>
  <header class="site-header"><div class="container header-inner"><a href="#" aria-label="Clínica Integra — início">${brand()}</a><nav class="site-nav" aria-label="Navegação principal"><a href="#especialidades">Especialidades</a><a href="sobre.html">Sobre e localização</a></nav><div class="header-actions"><button class="text-btn" data-action="patient-login">${icon('user')} Área do paciente</button><button class="btn" data-action="book">Agendar consulta ${icon('arrow')}</button></div></div></header>
  <main id="main"><section class="hero"><div class="container hero-inner"><div class="hero-copy"><div class="eyebrow">Clínica multidisciplinar · São Paulo</div><h1>Cuidar da saúde<br>faz parte <span>da vida.</span></h1><p>Consultas em seis especialidades, de segunda a sábado. Escolha o profissional e veja os horários disponíveis para o seu atendimento.</p><div class="hero-buttons"><button class="btn" data-action="book">Agendar consulta ${icon('arrow')}</button></div><p class="booking-note">Agendamento sujeito à confirmação da recepção.</p></div><div class="hero-visual"><img class="hero-photo" src="consultation.jpg" alt="Profissional de saúde conversando com uma paciente durante uma consulta ilustrativa" width="600" height="500" fetchpriority="high"><span class="photo-caption">Imagem ilustrativa</span></div></div></section>
  <section class="section" id="especialidades"><div class="container"><div class="section-heading"><div><div class="eyebrow">Nossas especialidades</div><h2>Especialidades</h2></div></div><div class="specialties">${SPECIALTIES.map(s=>`<button class="specialty-card" data-action="book" data-specialty="${s.id}"><div class="soft-icon">${icon(s.icon)}</div><div class="row"><h3>${s.name}</h3>${icon('arrow')}</div><p>${s.description}</p></button>`).join('')}</div></div></section>
  
  </main>
  <footer class="site-footer" id="atendimento"><div class="container"><div class="footer-grid"><div>${brand()}</div><div><b>Atendimento</b><span>Segunda a sexta · 8h às 18h</span><span>Sábado · 8h às 12h</span><span>Intervalo · 12h às 13h</span></div><div><b>Acesse</b><button class="text-btn" style="color:#adbed0;font-weight:400;padding:4px 0;font-size:12px" data-action="patient-login">Área do paciente</button><button class="text-btn" style="color:#adbed0;font-weight:400;padding:4px 0;font-size:12px" data-action="roles">Painel da equipe</button></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Clínica Integra · Demonstração com dados fictícios</span><span>Dados salvos somente neste navegador · <a href="https://unsplash.com/photos/tl447mekwuQ" target="_blank" rel="noopener">Foto: National Cancer Institute / Unsplash</a></span></div></div></footer>`;}

function roleModal(){openModal(modalHead('Explore a demonstração','Escolha um perfil para conhecer cada parte do template.')+`<div class="modal-body"><div class="notice">${icon('info')}<span>Os acessos são simulados e os dados ficam neste navegador. Use apenas informações fictícias.</span></div><div class="role-list" style="margin-top:20px">${[
  ['patient','user','Paciente','Acompanhe, cancele e remarque suas consultas.'],['admin','grid','Administrador','Agenda completa, pacientes, horários e relatórios.'],['reception','calendar','Recepção','Aprove solicitações e organize os atendimentos.'],['doctor','stethoscope','Profissional','Visualize somente sua própria agenda.']
].map(([role,ic,title,sub])=>`<button class="choice" data-action="choose-role" data-role="${role}"><span class="soft-icon">${icon(ic)}</span><span><b>${title}</b><small>${sub}</small></span>${icon('chevron')}</button>`).join('')}</div></div>`);}
function patientLogin(){openModal(modalHead('Área do paciente','Acesso demonstrativo, sem senha ou autenticação real.')+`<div class="modal-body"><button class="choice" style="width:100%" data-action="enter-demo-patient">${avatar('Mariana Costa')}<span><b>Entrar como Mariana Costa</b><small>Paciente fictícia com consultas de exemplo</small></span>${icon('arrow')}</button><div class="divider"></div><h3 class="section-subtitle">Ou crie um perfil de demonstração</h3><form id="patient-account" class="stack"><label class="field">Nome completo<input name="name" required minlength="3" maxlength="100" autocomplete="off" placeholder="Ex.: Maria Exemplo"></label><div class="form-grid"><label class="field">E-mail fictício<input name="email" type="email" required maxlength="120" autocomplete="off" placeholder="maria@example.com"></label><label class="field">Telefone fictício<input name="phone" type="tel" required minlength="10" maxlength="24" placeholder="(11) 90000-0000"></label></div><div class="notice">${icon('info')}<span>Para retornar a um perfil já criado neste navegador, informe o mesmo e-mail fictício.</span></div><div id="form-error"></div><button class="btn" type="submit">Entrar na demonstração ${icon('arrow')}</button></form></div>`);}
function doctorLogin(){openModal(modalHead('Escolha um profissional','A agenda será limitada ao profissional selecionado.')+`<div class="modal-body choice-grid">${DOCTORS.map(d=>`<button class="choice" data-action="enter-doctor" data-id="${d.id}">${avatar(d.name.replace(/Dra?\. /,''),d.color)}<span><b>${d.name}</b><small>${specialty(d.specialty).name}</small></span>${icon('chevron')}</button>`).join('')}</div>`);}

function navItems(){return session.role==='patient'?[['appointments','calendar','Minhas consultas'],['profile','user','Meus dados']]:[['overview','grid','Visão geral'],['agenda','calendar','Agenda'],['appointments','list','Agendamentos'],...(allowedTeam()?[['patients','users','Pacientes'],['availability','clock','Disponibilidade'],['reports','chart','Relatórios']]:[])];}
function userInfo(){if(session.role==='patient')return [patient(session.patientId)?.name,'Paciente'];if(session.role==='doctor')return [doctor(session.doctorId).name,specialty(doctor(session.doctorId).specialty).name];return session.role==='admin'?['Administrador','Gestão da clínica']:['Recepção Integra','Atendimento'];}
function workspace(){const [name,sub]=userInfo(),items=navItems(),current=items.find(n=>n[0]===page)||items[0];page=current[0];const pending=visibleAppointments().filter(a=>a.status==='pending').length;return `<div class="workspace"><aside class="sidebar"><a href="#" data-action="site">${brand()}</a><div class="sidebar-label">${session.role==='patient'?'Área do paciente':'Gestão da clínica'}</div><nav class="side-nav" aria-label="Menu do painel">${items.map(([id,ic,label])=>`<button class="${id===page?'active':''}" data-action="nav" data-page="${id}" ${id===page?'aria-current="page"':''}>${icon(ic)}<span class="nav-label">${label}</span>${id==='appointments'&&pending?`<span class="nav-count">${pending}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><div class="demo-box"><b>Ambiente de demonstração</b><p>Dados fictícios salvos neste navegador. Alterne os perfis para testar o fluxo completo.</p><button class="text-btn" style="font-size:10px;padding-bottom:0" data-action="roles">Trocar perfil ${icon('arrow')}</button></div><div class="side-user">${avatar(name)}<div class="grow"><b>${e(name)}</b><small>${e(sub)}</small></div><button class="icon-btn" data-action="site" aria-label="Sair do painel">${icon('logout')}</button></div></div></aside><div class="work-main"><header class="work-top"><div class="mobile-side"><button class="icon-btn" data-action="mobile-nav" aria-label="Abrir menu">${icon('menu')}</button><a data-action="site" href="#">${brand()}</a></div><div class="breadcrumb">${session.role==='patient'?'Área do paciente':'Painel da equipe'} ${icon('chevron')} <span>${current[2]}</span></div><div class="row"><span class="demo-pill">DEMONSTRAÇÃO</span><button class="text-btn" data-action="site">Ver site ${icon('external')}</button></div></header><main class="work-content" id="main">${pageContent()}</main></div></div>`;}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="row wrap">${actions}</div></div>`;}
function metric(title,value,note,ic){return `<div class="metric"><div class="metric-top"><span>${title}</span>${icon(ic)}</div><strong>${value}</strong><small>${note}</small></div>`;}
function pageContent(){if(session.role==='patient')return page==='profile'?profileView():patientView();switch(page){case'overview':return overview();case'agenda':return agendaView();case'appointments':return recordsView();case'patients':return patientsView();case'availability':return availabilityView();case'reports':return reportsView();default:return overview();}}
function overview(){const all=visibleAppointments(),today=clinicNow().date,todays=all.filter(a=>a.date===today),pending=all.filter(a=>a.status==='pending'),name=userInfo()[0];return heading(`Olá, ${e(session.role==='doctor'?name:'equipe Integra')}.`,`Confira a agenda e as solicitações da clínica · ${fmt(today,{weekday:'long',day:'numeric',month:'long'})}`,allowedTeam()?`<button class="btn" data-action="manual-book">${icon('plus')} Novo agendamento</button>`:'')+`<div class="metrics">${metric('Consultas hoje',todays.filter(a=>!['cancelled','rejected'].includes(a.status)).length,'Atendimentos previstos','calendar')}${metric('Aguardando aprovação',pending.length,'Solicitações em aberto','clock')}${metric('Confirmadas hoje',todays.filter(a=>a.status==='confirmed').length,'Prontas para atendimento','check')}${metric('Pacientes',new Set(all.map(a=>a.patientId)).size,'Com agendamentos na agenda','users')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Agenda de hoje</h2><p>${fmt(today,{day:'numeric',month:'long',year:'numeric'})} · Horário de Brasília</p></div><button class="text-btn" style="font-size:10px" data-action="nav" data-page="agenda">Ver agenda ${icon('arrow')}</button></div>${appointmentTable(todays.sort(sortAppointments),true)}<div class="small-info">${todays.length} agendamento(s) nesta data · Clique em detalhes para acompanhar.</div></section><section class="panel"><div class="panel-head"><div><h2>Solicitações pendentes</h2><p>${pending.length} aguardando análise</p></div>${icon('clock')}</div><div class="pending-list">${pending.sort(sortAppointments).slice(0,4).map(a=>`<div class="pending-card"><div class="row">${avatar(patient(a.patientId).name)}<b>${e(patient(a.patientId).name)}</b></div><p>${specialty(doctor(a.doctorId).specialty).name}<br>${fmt(a.date)} às ${a.time} · ${e(doctor(a.doctorId).name)}</p><div class="row">${allowedTeam()?`<button class="btn small" data-action="whatsapp-decision" data-id="${a.id}" data-status="confirmed">Confirmar pelo WhatsApp</button><button class="btn danger small" data-action="whatsapp-decision" data-id="${a.id}" data-status="rejected">Recusar pelo WhatsApp</button>`:''}<button class="btn light small" data-action="detail" data-id="${a.id}">Ver detalhes</button></div></div>`).join('')||empty('Nenhuma solicitação pendente','As próximas solicitações aparecerão aqui.','check')}</div></section></div>`;}
function sortAppointments(a,b){return `${a.date} ${a.time}`.localeCompare(`${b.date} ${b.time}`);}
function empty(title,description='',ic='calendar'){return `<div class="empty">${icon(ic)}<h3>${title}</h3>${description?`<p>${description}</p>`:''}</div>`;}
function appointmentTable(list,compact=false){return list.length?`<div class="table-scroll"><table><thead><tr><th>Paciente</th><th>Consulta</th>${compact?'':'<th>Agendado em</th>'}<th>Status</th><th>Ações</th></tr></thead><tbody>${list.map(a=>{const d=doctor(a.doctorId),p=patient(a.patientId);return `<tr><td><div class="patient-cell">${avatar(p.name)}<div><b>${e(p.name)}</b><small>${e(p.phone)}</small></div></div></td><td><b>${fmt(a.date)} · ${a.time}</b><small>${e(d.name)} · ${specialty(d.specialty).name}</small></td>${compact?'':`<td><b>${stamp(a.createdAt).split(',')[0]}</b><small>${stamp(a.createdAt).split(',')[1]||''}</small></td>`}<td>${badge(a.status)}</td><td><button class="table-action" data-action="detail" data-id="${a.id}">Detalhes</button></td></tr>`;}).join('')}</tbody></table></div>`:empty('Nenhum agendamento encontrado','Tente outra data ou ajuste os filtros.');}
function recordsList(){return visibleAppointments().filter(a=>{const p=patient(a.patientId),d=doctor(a.doctorId),query=filters.search.toLocaleLowerCase('pt-BR');return (!filters.status||a.status===filters.status)&&(!filters.doctor||a.doctorId===filters.doctor)&&(!filters.date||a.date===filters.date)&&(!query||[p.name,p.email,p.phone,d.name,a.id].some(v=>v.toLocaleLowerCase('pt-BR').includes(query)));}).sort(sortAppointments);}
function recordsView(){return heading('Agendamentos','Veja quem agendou, quando solicitou e os detalhes de cada consulta.',allowedTeam()?`<button class="btn" data-action="manual-book">${icon('plus')} Novo agendamento</button>`:'')+`<section class="panel"><div class="filters"><input class="search" id="filter-search" aria-label="Buscar agendamentos" placeholder="Buscar paciente, profissional ou código..." value="${e(filters.search)}"><select id="filter-status" aria-label="Filtrar por status"><option value="">Todos os status</option>${Object.entries(STATUS).map(([k,v])=>`<option value="${k}" ${filters.status===k?'selected':''}>${v}</option>`).join('')}</select>${allowedTeam()?`<select id="filter-doctor" aria-label="Filtrar por profissional"><option value="">Todos os profissionais</option>${DOCTORS.map(d=>`<option value="${d.id}" ${filters.doctor===d.id?'selected':''}>${d.name}</option>`).join('')}</select>`:''}<input type="date" id="filter-date" aria-label="Filtrar data da consulta" value="${filters.date}"><button class="icon-btn" data-action="clear-filters" aria-label="Limpar filtros">${icon('refresh')}</button></div><div id="records-table">${appointmentTable(recordsList())}</div><div class="small-info" id="records-count">${recordsList().length} agendamento(s) · Horário de Brasília</div></section>`;}
function agendaView(){const docs=session.role==='doctor'?DOCTORS.filter(d=>d.id===session.doctorId):DOCTORS;return heading('Agenda',fmt(selectedDate,{weekday:'long',day:'numeric',month:'long',year:'numeric'}),`<div class="day-nav"><button class="icon-btn" data-action="day" data-offset="-1" aria-label="Dia anterior">${icon('back')}</button><input type="date" id="agenda-date" aria-label="Data da agenda" value="${selectedDate}"><button class="icon-btn" data-action="day" data-offset="1" aria-label="Próximo dia">${icon('chevron')}</button><button class="btn light small" data-action="today">Hoje</button></div>`)+`<div class="agenda-grid">${docs.map(d=>{const list=visibleAppointments().filter(a=>a.date===selectedDate&&a.doctorId===d.id&&!['cancelled','rejected'].includes(a.status)).sort(sortAppointments),blocks=db.blocks.filter(b=>b.date===selectedDate&&(b.doctorId==='all'||b.doctorId===d.id));return `<section class="agenda-doctor"><div class="agenda-doctor-head">${avatar(d.name.replace(/Dra?\. /,''),d.color)}<div><b>${d.name}</b><small>${specialty(d.specialty).name}</small></div></div>${list.map(a=>`<div class="agenda-entry"><strong>${a.time}</strong><div><b>${e(patient(a.patientId).name)}</b>${badge(a.status)}<br><button data-action="detail" data-id="${a.id}">Ver consulta ${icon('chevron')}</button></div></div>`).join('')}${blocks.map(b=>`<div class="notice amber" style="margin:12px;font-size:10px">${icon('lock')}<span>${b.start}–${b.end} · ${e(b.reason||'Horário bloqueado')}</span></div>`).join('')}${!list.length?'<div class="calendar-empty">Nenhuma consulta nesta data</div>':''}<div class="small-info">${weekday(selectedDate)===0?'Sem atendimento aos domingos':`${slots(db,d.id,selectedDate).length} horário(s) disponível(is)`}</div></section>`;}).join('')}</div>`;}

function patientsView(){return heading('Pacientes','Cadastros fictícios e histórico de agendamentos.')+`<section class="panel"><div class="filters"><input class="search" id="patient-search" aria-label="Buscar paciente" placeholder="Buscar nome, e-mail ou telefone..."></div><div id="patients-table">${patientsTable('')}</div></section>`;}
function patientsTable(query){const ps=db.patients.filter(p=>[p.name,p.email,p.phone].some(v=>v.toLowerCase().includes(query.toLowerCase())));return ps.length?`<div class="table-scroll"><table><thead><tr><th>Paciente</th><th>Contato</th><th>Consultas</th><th>Histórico</th></tr></thead><tbody>${ps.map(p=>`<tr><td><div class="patient-cell">${avatar(p.name)}<b>${e(p.name)}</b></div></td><td><b>${e(p.email)}</b><small>${e(p.phone)}</small></td><td>${db.appointments.filter(a=>a.patientId===p.id).length} agendamento(s)</td><td><button class="table-action" data-action="patient-history" data-id="${p.id}">Ver agendamentos</button></td></tr>`).join('')}</tbody></table></div>`:empty('Paciente não encontrado','Busque por outro nome ou contato.','users');}

function patientView(){const list=visibleAppointments().sort(sortAppointments),future=list.filter(a=>['pending','confirmed'].includes(a.status)&&`${a.date} ${a.time}`>=`${clinicNow().date} ${clinicNow().time}`),history=list.filter(a=>!future.includes(a));return heading('Minhas consultas',`Olá, ${e(patient(session.patientId).name.split(' ')[0])}. Acompanhe seus agendamentos por aqui.`,`<button class="btn" data-action="book">${icon('plus')} Agendar consulta</button>`)+`<div class="notice" style="margin-bottom:24px">${icon('info')}<span>Novas solicitações e remarcações precisam de aprovação da recepção. As atualizações aparecem nesta área.</span></div><h2 class="section-subtitle">Próximas consultas <span class="muted">(${future.length})</span></h2><div class="patient-grid">${future.map(a=>appointmentCard(a,true)).join('')||`<section class="panel full">${empty('Seu próximo cuidado começa aqui','Escolha uma especialidade e encontre um horário disponível.')}</section>`}</div>${history.length?`<h2 class="section-subtitle">Histórico de consultas</h2><div class="patient-grid">${history.reverse().map(a=>appointmentCard(a,false)).join('')}</div>`:''}`;}
function appointmentCard(a,canManage){const d=doctor(a.doctorId);return `<article class="appointment-card"><div class="row"><div class="date-box"><strong>${fmt(a.date,{day:'2-digit'})}</strong><small>${fmt(a.date,{month:'short'})}</small></div><div class="grow">${badge(a.status)}<h3>${specialty(d.specialty).name}</h3><p>${d.name}</p></div></div><div class="card-meta"><span>${icon('clock')} ${a.time} · ${duration(d.id)} min</span><span>${icon('pin')} Atendimento presencial</span></div><div class="row spread wrap"><small class="muted">Código ${a.id}</small><div class="row">${canManage?`<button class="text-btn" style="font-size:11px" data-action="reschedule" data-id="${a.id}">Remarcar</button><button class="text-btn" style="font-size:11px;color:#a65c5c" data-action="cancel" data-id="${a.id}">Cancelar</button>`:`<button class="text-btn" style="font-size:11px" data-action="detail" data-id="${a.id}">Ver detalhes</button>`}</div></div></article>`;}
function profileView(){const p=patient(session.patientId);return heading('Meus dados','Informações do seu perfil demonstrativo.')+`<section class="panel" style="max-width:700px"><div class="panel-head"><h2>Dados do paciente</h2></div><form id="profile-form" class="panel-body stack"><label class="field">Nome completo<input name="name" value="${e(p.name)}" required minlength="3" maxlength="100"></label><div class="form-grid"><label class="field">E-mail fictício<input name="email" type="email" value="${e(p.email)}" required maxlength="120"></label><label class="field">Telefone fictício<input name="phone" type="tel" value="${e(p.phone)}" required minlength="10" maxlength="24"></label></div><p class="hint">Este perfil existe apenas neste navegador. Não informe dados pessoais reais.</p><div id="profile-error"></div><div><button class="btn" type="submit">Salvar dados</button></div></form></section>`;}

function availabilityView(){return heading('Disponibilidade','Gerencie o horário de funcionamento e os bloqueios da equipe.',`<button class="btn" data-action="block-modal">${icon('plus')} Bloquear horário</button>`)+`<div class="report-grid"><section class="panel"><div class="panel-head"><h2>Horário de funcionamento</h2></div><form id="hours-form" class="panel-body stack"><div class="notice">${icon('info')}<span>Domingos fechados. Consultas de 30 ou 60 minutos, conforme a especialidade. Fuso de Brasília.</span></div><div class="form-grid">${[['start','Abertura · segunda a sábado'],['end','Fechamento · segunda a sexta'],['breakStart','Início do intervalo'],['breakEnd','Fim do intervalo'],['saturdayEnd','Fechamento · sábado']].map(([key,label])=>`<label class="field">${label}<input type="time" name="${key}" value="${db.hours[key]}" step="1800" required ${session.role!=='admin'?'disabled':''}></label>`).join('')}</div><div id="hours-error"></div>${session.role==='admin'?'<div><button class="btn" type="submit">Salvar horários</button></div>':'<p class="hint">O administrador configura o funcionamento. A recepção pode criar e remover bloqueios.</p>'}</form></section><section class="panel"><div class="panel-head"><div><h2>Horários bloqueados</h2><p>Férias, feriados e indisponibilidades</p></div></div>${db.blocks.length?db.blocks.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(b=>`<div class="pending-card"><div class="row spread"><div><b>${b.doctorId==='all'?'Toda a clínica':doctor(b.doctorId).name}</b><p>${fmt(b.date)} · ${b.start} às ${b.end}<br>${e(b.reason||'Indisponível')}</p></div><button class="icon-btn" data-action="remove-block" data-id="b-${b.id}" aria-label="Remover bloqueio">${icon('close')}</button></div></div>`).join(''):empty('Nenhum bloqueio cadastrado','Os horários seguem o funcionamento da clínica.','clock')}</section></div>`;}
function reportsView(){const list=db.appointments.filter(a=>a.date>=reportStart&&a.date<=reportEnd),confirmed=list.filter(a=>['confirmed','completed'].includes(a.status)).length,completed=list.filter(a=>a.status==='completed').length;return heading('Relatórios','Indicadores ilustrativos com base nos agendamentos deste navegador.',`<button class="btn light" data-action="export">${icon('download')} Exportar CSV</button>`)+`<div class="filters" style="padding:0 0 20px;border:0"><label class="field">De<input id="report-start" type="date" value="${reportStart}" max="${reportEnd}"></label><label class="field">Até<input id="report-end" type="date" value="${reportEnd}" min="${reportStart}"></label><span class="hint">Período pela data da consulta</span></div><div class="metrics">${metric('Agendamentos',list.length,'No período selecionado','calendar')}${metric('Realizadas',completed,'Atendimentos concluídos','check')}${metric('Aprovadas',confirmed,'Confirmadas + realizadas','shield')}${metric('Pacientes atendidos',new Set(list.filter(a=>a.status==='completed').map(a=>a.patientId)).size,'Com consultas realizadas','users')}</div><div class="report-grid"><section class="panel"><div class="panel-head"><h2>Agendamentos por especialidade</h2></div><div class="panel-body">${SPECIALTIES.map(s=>chartRow(s.name,list.filter(a=>doctor(a.doctorId).specialty===s.id).length,list.length)).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Situação dos agendamentos</h2></div><div class="panel-body">${Object.entries(STATUS).map(([s,label])=>chartRow(label,list.filter(a=>a.status===s).length,list.length,s==='completed'?'#6a9f8b':s==='pending'?'#c6a25d':'#6e93b8')).join('')}</div></section></div><p class="hint" style="margin-top:16px">Indicadores para demonstração. O arquivo CSV inclui os filtros de período acima.</p>`;}
function chartRow(label,n,total,color='#5884b2'){return `<div class="chart-row"><span class="chart-label">${label}</span><div class="chart-track" role="img" aria-label="${label}: ${n}"><div class="chart-fill" style="width:${total?n/total*100:0}%;background:${color}"></div></div><b>${n}</b></div>`;}

function startBooking({specialtyId='',appointmentId=null,manual=false}={}) {
  const a=appointmentId?db.appointments.find(a=>a.id===appointmentId):null;
  if(appointmentId&&(!a||!canAccess(a)||!canManage(a)))return toast('Esta consulta não pode ser remarcada.');
  booking={step:a?2:(specialtyId?1:0),specialty:a?doctor(a.doctorId).specialty:specialtyId,doctorId:a?.doctorId||'',date:'',time:'',offset:0,appointmentId,manual,patientId:a?.patientId||(session?.role==='patient'?session.patientId:''),name:'',email:'',phone:'',notes:a?.notes||''};
  renderBooking();
}
function renderBooking(error='') {
  const b=booking;if(!b)return;
  const titles=['Escolha uma especialidade','Escolha um profissional','Escolha a data e o horário','Revise sua solicitação'];
  let content='';
  if(b.step===0)content=`<div class="choice-grid">${SPECIALTIES.map(s=>`<button class="choice ${b.specialty===s.id?'selected':''}" data-action="select-specialty" data-id="${s.id}"><span class="soft-icon">${icon(s.icon)}</span><span><b>${s.name}</b><small>Consulta · ${s.duration} minutos</small></span>${icon('chevron')}</button>`).join('')}</div>`;
  if(b.step===1)content=`<div class="stack">${DOCTORS.filter(d=>d.specialty===b.specialty).map(d=>`<button class="choice ${b.doctorId===d.id?'selected':''}" data-action="select-doctor" data-id="${d.id}">${avatar(d.name.replace(/Dra?\. /,''),d.color)}<span><b>${d.name}</b><small>${specialty(d.specialty).name} · ${duration(d.id)} minutos</small><small>${d.bio}</small></span>${icon('chevron')}</button>`).join('')}<p class="hint">Todos os profissionais e perfis são fictícios.</p></div>`;
  if(b.step===2){
    const today=clinicNow().date,first=addDays(today,b.offset),last=addDays(first,13),available=b.date?slots(db,b.doctorId,b.date,{excludeId:b.appointmentId}):[];
    content=`<div class="row" style="margin-bottom:21px">${avatar(doctor(b.doctorId).name,doctor(b.doctorId).color)}<div><b style="font-size:13px">${doctor(b.doctorId).name}</b><p style="font-size:11px;color:var(--muted)">${specialty(b.specialty).name} · ${duration(b.doctorId)} minutos</p></div></div><div class="row spread"><b style="font-size:13px;text-transform:capitalize">${fmt(first,{month:'long',year:'numeric'})}${first.slice(0,7)!==last.slice(0,7)?` / ${fmt(last,{month:'long'})}`:''}</b><div class="row"><button class="icon-btn" data-action="dates-page" data-offset="-14" ${b.offset===0?'disabled':''} aria-label="Datas anteriores">${icon('back')}</button><button class="icon-btn" data-action="dates-page" data-offset="14" ${b.offset>=84?'disabled':''} aria-label="Próximas datas">${icon('chevron')}</button></div></div><div class="date-grid">${Array.from({length:14},(_,i)=>addDays(first,i)).map(date=>`<button class="date-choice ${b.date===date?'selected':''}" data-action="select-date" data-date="${date}" ${!slots(db,b.doctorId,date,{excludeId:b.appointmentId}).length?'disabled':''} aria-label="${fmt(date,{weekday:'long',day:'numeric',month:'long'})}"><small>${fmt(date,{weekday:'short'}).replace('.','')}</small><strong>${fmt(date,{day:'2-digit'})}</strong></button>`).join('')}</div><h3 class="section-subtitle">${b.date?`Horários para ${fmt(b.date,{day:'numeric',month:'long'})}`:'Selecione uma data acima'}</h3>${b.date?`<div class="slot-grid">${available.map(time=>`<button class="slot ${b.time===time?'selected':''}" data-action="select-time" data-time="${time}">${time}</button>`).join('')}</div>${!available.length?empty('Sem horários nesta data','Escolha outro dia.','clock'):''}`:''}<p class="hint" style="margin-top:19px">${icon('clock')} Horário de Brasília · Agendamentos com até 90 dias de antecedência.</p>`;
  }
  if(b.step===3){
    const p=patient(b.patientId);
    content=`${bookingSummary()}<form id="booking-form" class="stack">${b.manual?`<label class="field">Paciente<select name="patientId" required><option value="">Selecione um paciente cadastrado</option>${db.patients.map(p=>`<option value="${p.id}" ${b.patientId===p.id?'selected':''}>${e(p.name)} · ${e(p.email)}</option>`).join('')}</select></label>`:p?`<div class="row">${avatar(p.name)}<div><b style="font-size:13px">${e(p.name)}</b><p class="hint" style="margin:3px 0">${e(p.email)} · ${e(p.phone)}</p></div></div>`:`<div class="notice">${icon('user')}<span>Um perfil de demonstração será criado para acompanhar esta consulta. Use informações fictícias.</span></div><div class="form-grid"><label class="field full">Nome completo<input name="name" required minlength="3" maxlength="100" placeholder="Ex.: Maria Exemplo" value="${e(b.name)}" autocomplete="off"></label><label class="field">E-mail fictício<input name="email" required type="email" maxlength="120" placeholder="maria@example.com" value="${e(b.email)}" autocomplete="off"></label><label class="field">Telefone fictício<input name="phone" required type="tel" minlength="10" maxlength="24" placeholder="(11) 90000-0000" value="${e(b.phone)}"></label></div>`}<label class="field">Observação de agendamento <span class="muted">(opcional)</span><textarea name="notes" rows="2" maxlength="300" placeholder="Ex.: Preciso de acesso por elevador. Não inclua informações de saúde.">${e(b.notes)}</textarea></label><div class="notice amber">${icon('clock')}<span>Esta solicitação ficará <b>aguardando aprovação</b>. A recepção confirmará a consulta na área do paciente. Nenhuma mensagem externa será enviada nesta demonstração.</span></div><div id="booking-error">${error?`<div class="error">${e(error)}</div>`:''}</div></form>`;
  }
  openModal(modalHead(b.appointmentId?'Remarcar consulta':'Agendar consulta',titles[b.step])+`<div class="stepper">${['Especialidade','Profissional','Horário','Seus dados'].map((label,i)=>`<div class="${i<=b.step?'active':''}"><b>${i<b.step?'✓':i+1}</b><span>${label}</span></div>`).join('')}</div><div class="modal-body">${content}${error&&b.step!==3?`<div class="error">${e(error)}</div>`:''}</div><div class="modal-footer"><button class="btn light" data-action="booking-back">${icon('back')} ${b.step?'Voltar':'Fechar'}</button>${b.step===2?`<button class="btn" data-action="booking-next" ${!b.date||!b.time?'disabled':''}>Continuar ${icon('arrow')}</button>`:b.step===3?'<button class="btn" type="submit" form="booking-form">Solicitar agendamento</button>':'<small>Selecione uma opção para continuar</small>'}</div>`);
}
function bookingSummary(){const b=booking;return `<div class="summary-card"><div class="summary-line">${icon('stethoscope')}<b>${specialty(b.specialty).name}</b><span class="muted">· ${doctor(b.doctorId).name}</span></div><div class="row wrap"><span class="summary-line">${icon('calendar')}${fmt(b.date,{day:'numeric',month:'long',year:'numeric'})}</span><span class="summary-line">${icon('clock')}${b.time} · ${duration(b.doctorId)} minutos</span></div><div class="summary-line">${icon('pin')}Unidade demonstrativa · Atendimento presencial</div></div>`;}
function rememberBookingFields(){const f=document.querySelector('#booking-form');if(f&&booking){const values=Object.fromEntries(new FormData(f));for(const k of ['name','email','phone','notes','patientId'])if(k in values)booking[k]=values[k];}}
function canAccess(a){return allowedTeam()||(session?.role==='doctor'&&a.doctorId===session.doctorId)||(session?.role==='patient'&&a.patientId===session.patientId);}
function canManage(a){return ['pending','confirmed'].includes(a.status)&&`${a.date} ${a.time}`>=`${clinicNow().date} ${clinicNow().time}`;}
function pendingWhatsappDecision(id,status){
  db=readDb();
  const a=db.appointments.find(item=>item.id===id);
  if(!allowedTeam()||!a||a.status!=='pending'||!['confirmed','rejected'].includes(status))return toast('Esta solicitação já foi analisada.');
  const title=status==='confirmed'?'Confirmar consulta':'Recusar solicitação';
  openModal(modalHead(title,'O status será atualizado antes de preparar a mensagem.')+'<div class="modal-body"><p>'+e(patient(a.patientId).name)+' · '+fmt(a.date)+' às '+a.time+'</p><p class="hint">'+(status==='confirmed'?'A consulta ficará confirmada na área do paciente.':'A solicitação ficará não aprovada e o horário será liberado.')+' Você poderá revisar a mensagem em seguida. O envio no WhatsApp é manual.</p></div><div class="modal-footer"><button class="btn light" data-action="close">Voltar</button><button class="btn" data-action="apply-whatsapp-decision" data-id="'+e(id)+'" data-status="'+status+'">'+title+' e preparar mensagem</button></div>');
}
function whatsappConfirmation(id){
  db=readDb();
  const a=db.appointments.find(item=>item.id===id);
  if(!allowedTeam()||!a||!['confirmed','rejected'].includes(a.status))return toast('Confirme ou recuse a solicitação antes de preparar a mensagem.');
  const p=patient(a.patientId);
  let number=p.phone.replace(/\D/g,'');
  if(number.length===10||number.length===11)number='55'+number;
  if(!/^55[1-9][0-9]{9,10}$/.test(number))return toast('Cadastre um telefone brasileiro válido com DDD para o paciente.');
  const message=a.status==='rejected'
    ? 'Olá, '+p.name.split(' ')[0]+'! Não foi possível confirmar sua solicitação na Clínica Integra para '+fmt(a.date,{day:'2-digit',month:'2-digit',year:'numeric'})+' às '+a.time+'. Esse horário não está reservado. Entre em contato com a recepção para consultar outras opções. Código: '+a.id+'.'
    : 'Olá, '+p.name.split(' ')[0]+'! Sua consulta na Clínica Integra está confirmada para '+fmt(a.date,{day:'2-digit',month:'2-digit',year:'numeric'})+' às '+a.time+'. Se precisar cancelar ou remarcar, entre em contato com a recepção. Código: '+a.id+'.';
  const url='https://wa.me/'+number+'?text='+encodeURIComponent(message);
  openModal(modalHead(a.status==='rejected'?'Recusa pelo WhatsApp':'Confirmação pelo WhatsApp','Revise o número e a mensagem antes de abrir a conversa.')+'<div class="modal-body stack"><div class="notice amber">'+icon('info')+'<span>Esta demonstração contém telefones fictícios. Confira o destinatário antes de continuar. A mensagem só será enviada quando você tocar em Enviar no WhatsApp.</span></div><div><small class="muted">Destinatário</small><p>'+e(p.name)+' · '+e(p.phone)+'</p></div><div class="summary-card" style="white-space:pre-wrap;margin-bottom:0">'+e(message)+'</div><p class="hint">Nenhuma informação clínica ou observação do paciente é incluída. Abrir a conversa não confirma a entrega da mensagem.</p></div><div class="modal-footer"><button class="btn light" data-action="detail" data-id="'+e(a.id)+'">Voltar</button><a class="btn" href="'+e(url)+'" target="_blank" rel="noopener noreferrer">Abrir WhatsApp '+icon('external')+'</a></div>');
}
function detail(id){const a=db.appointments.find(a=>a.id===id);if(!a||!canAccess(a))return;const p=patient(a.patientId),d=doctor(a.doctorId),team=allowedTeam(),clinical=session.role==='doctor';openModal(modalHead('Detalhes do agendamento',`Código ${a.id}`)+`<div class="modal-body"><div class="row spread" style="margin-bottom:23px"><div class="row">${avatar(p.name)}<div><h3 style="font-size:16px">${e(p.name)}</h3><p class="hint" style="margin:4px 0">${e(p.email)}</p></div></div>${badge(a.status)}</div><div class="detail-grid"><div><small>Especialidade</small><b>${specialty(d.specialty).name}</b></div><div><small>Profissional</small><b>${d.name}</b></div><div><small>Data e horário da consulta</small><b>${fmt(a.date,{day:'numeric',month:'long',year:'numeric'})} às ${a.time}</b></div><div><small>Duração</small><b>${duration(d.id)} minutos</b></div><div><small>Agendamento solicitado em</small><b>${stamp(a.createdAt)}</b></div><div><small>Telefone do paciente</small><b>${e(p.phone)}</b></div></div>${a.notes?`<div class="notice" style="margin-top:20px">${icon('info')}<span>${e(a.notes)}</span></div>`:''}<h3 class="section-subtitle">Histórico</h3><div class="timeline">${a.history.map(h=>`<div><b>${e(h.action)}</b><small>${stamp(h.at)}</small></div>`).join('')}</div></div><div class="modal-footer" style="justify-content:end;flex-wrap:wrap">${team&&a.status==='confirmed'?`<button class="btn pale small" data-action="whatsapp" data-id="${a.id}">Confirmar pelo WhatsApp</button>`:''}${team&&a.status==='pending'?`<button class="btn danger small" data-action="reject" data-id="${a.id}">Não aprovar</button><button class="btn small" data-action="status" data-id="${a.id}" data-status="confirmed">${icon('check')} Aprovar consulta</button>`:''}${(team||clinical)&&a.status==='confirmed'?`<button class="btn light small" data-action="status" data-id="${a.id}" data-status="missed">Registrar falta</button><button class="btn small" data-action="status" data-id="${a.id}" data-status="completed">Marcar realizada</button>`:''}${(team||session.role==='patient')&&canManage(a)?`<button class="btn light small" data-action="reschedule" data-id="${a.id}">Remarcar</button><button class="btn danger small" data-action="cancel" data-id="${a.id}">Cancelar</button>`:''}${!['pending','confirmed'].includes(a.status)?'<button class="btn light small" data-action="close">Fechar</button>':''}</div>`);}
function confirmStatus(id,status){const a=db.appointments.find(a=>a.id===id);if(!a||!canAccess(a))return;if(session.role==='patient'&&!canManage(a))return;const label=status==='cancelled'?'Cancelar consulta':'Não aprovar solicitação';openModal(modalHead(label)+`<div class="modal-body"><p style="font-size:13px">${status==='cancelled'?'O horário será liberado para outro agendamento.':'A solicitação ficará como não aprovada e o horário será liberado.'}</p><div class="summary-card" style="margin:20px 0 0"><b style="font-size:13px">${e(patient(a.patientId).name)}</b><span style="font-size:12px">${specialty(doctor(a.doctorId).specialty).name} · ${fmt(a.date)} às ${a.time}</span></div></div><div class="modal-footer"><button class="btn light" data-action="detail" data-id="${a.id}">Voltar</button><button class="btn danger" data-action="status" data-id="${a.id}" data-status="${status}">Confirmar ${status==='cancelled'?'cancelamento':'recusa'}</button></div>`);}
function updateStatus(id,status){db=readDb();const a=db.appointments.find(a=>a.id===id);if(!a||!canAccess(a))return;const team=allowedTeam(),clinical=session.role==='doctor',own=session.role==='patient';let valid=false;
  if(status==='confirmed')valid=team&&a.status==='pending';
  if(status==='rejected')valid=team&&a.status==='pending';
  if(['completed','missed'].includes(status))valid=(team||clinical)&&a.status==='confirmed';
  if(status==='cancelled')valid=(team||own)&&['confirmed','pending'].includes(a.status)&&(team||canManage(a));
  if(!valid)return toast('Esta ação não está disponível para a consulta.');
  if(['completed','missed'].includes(status)&&`${a.date} ${a.time}`>`${clinicNow().date} ${clinicNow().time}`)return toast('Registre a realização ou a falta a partir do horário da consulta.');
  a.status=status;a.history.push({action:({confirmed:'Consulta aprovada pela recepção',completed:'Atendimento realizado',cancelled:'Consulta cancelada',rejected:'Solicitação não aprovada',missed:'Não comparecimento registrado'})[status],at:new Date().toISOString()});persist();closeModal();render();toast(status==='confirmed'?'Consulta aprovada. O status foi atualizado para o paciente.':'Agendamento atualizado.');
}
function blockModal(){if(!allowedTeam())return;openModal(modalHead('Bloquear horário','O bloqueio impede novos agendamentos no intervalo escolhido.')+`<form id="block-form"><div class="modal-body stack"><label class="field">Profissional<select name="doctorId"><option value="all">Toda a clínica</option>${DOCTORS.map(d=>`<option value="${d.id}">${d.name}</option>`).join('')}</select></label><div class="form-grid"><label class="field full">Data<input name="date" type="date" required min="${clinicNow().date}" value="${addDays(clinicNow().date,1)}"></label><label class="field">Das<input name="start" type="time" step="1800" required value="08:00"></label><label class="field">Até<input name="end" type="time" step="1800" required value="18:00"></label></div><label class="field">Motivo<input name="reason" maxlength="100" placeholder="Ex.: Feriado, férias, reunião"></label><div class="notice">${icon('info')}<span>Se houver consultas no intervalo, será necessário remarcá-las ou cancelá-las antes.</span></div><div id="form-error"></div></div><div class="modal-footer"><button class="btn light" type="button" data-action="close">Voltar</button><button class="btn" type="submit">Salvar bloqueio</button></div></form>`);}
function exportCsv(){if(!allowedTeam())return;const rows=[['Código','Paciente','E-mail','Telefone','Especialidade','Profissional','Data da consulta','Hora','Status','Agendado em']];db.appointments.filter(a=>a.date>=reportStart&&a.date<=reportEnd).sort(sortAppointments).forEach(a=>{const p=patient(a.patientId),d=doctor(a.doctorId);rows.push([a.id,p.name,p.email,p.phone,specialty(d.specialty).name,d.name,a.date,a.time,STATUS[a.status],stamp(a.createdAt)]);});const csv='\uFEFF'+rows.map(row=>row.map(value=>{let s=String(value);if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=`integra-agendamentos-${reportStart}-${reportEnd}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Relatório exportado em CSV.');}
function showError(id,error){const target=document.getElementById(id);if(target){target.innerHTML=`<div class="error" role="alert">${e(error.message||error)}</div>`;target.scrollIntoView({block:'nearest',behavior:'smooth'});}else toast(error.message||error);}

document.addEventListener('click',event=>{
  const button=event.target.closest('[data-action]');if(!button||button.disabled)return;event.preventDefault();
  const action=button.dataset.action,id=button.dataset.id;
  switch(action){
    case'close':closeModal();break;
    case'roles':roleModal();break;
    case'patient-login':patientLogin();break;
    case'choose-role':if(button.dataset.role==='patient')patientLogin();else if(button.dataset.role==='doctor')doctorLogin();else setRole(button.dataset.role);break;
    case'enter-demo-patient':setRole('patient',{patientId:'mariana'});break;
    case'enter-doctor':if(doctor(id))setRole('doctor',{doctorId:id});break;
    case'site':session=null;saveSession();closeModal();render();window.scrollTo(0,0);break;
    case'nav':if(navItems().some(n=>n[0]===button.dataset.page)){page=button.dataset.page;closeModal();render();window.scrollTo(0,0);}break;
    case'mobile-nav':openModal(modalHead('Menu do painel',userInfo()[0])+`<div class="modal-body mobile-nav-dialog">${navItems().map(([p,ic,label])=>`<button class="btn ${p===page?'':'light'}" data-action="nav" data-page="${p}">${icon(ic)} ${label}</button>`).join('')}<div class="divider"></div><button class="btn light" data-action="roles">${icon('users')} Trocar perfil</button><button class="btn light" data-action="site">${icon('external')} Ver site</button></div>`);break;
    case'book':startBooking({specialtyId:button.dataset.specialty||'',manual:allowedTeam()});break;
    case'manual-book':if(allowedTeam())startBooking({manual:true});break;
    case'select-specialty':if(booking&&specialty(id)){booking.specialty=id;booking.doctorId='';booking.date='';booking.time='';booking.step=1;renderBooking();}break;
    case'select-doctor':if(booking&&doctor(id)?.specialty===booking.specialty){booking.doctorId=id;booking.date='';booking.time='';booking.step=2;renderBooking();}break;
    case'select-date':if(booking){booking.date=button.dataset.date;booking.time='';renderBooking();}break;
    case'select-time':if(booking){booking.time=button.dataset.time;renderBooking();}break;
    case'dates-page':if(booking){booking.offset=Math.max(0,Math.min(84,booking.offset+Number(button.dataset.offset)));renderBooking();}break;
    case'booking-next':if(booking?.date&&booking.time){booking.step=3;renderBooking();}break;
    case'booking-back':if(booking){rememberBookingFields();if(booking.step>0){booking.step--;renderBooking();}else closeModal();}break;
    case'detail':detail(id);break;
    case'whatsapp':whatsappConfirmation(id);break;
    case'whatsapp-decision':pendingWhatsappDecision(id,button.dataset.status);break;
    case'apply-whatsapp-decision':{
      const status=button.dataset.status;
      db=readDb();
      const a=db.appointments.find(item=>item.id===id);
      if(allowedTeam()&&a?.status==='pending'&&['confirmed','rejected'].includes(status)){
        updateStatus(id,status);
        if(db.appointments.find(item=>item.id===id)?.status===status)whatsappConfirmation(id);
      }else{closeModal();render();toast('Esta solicitação já foi analisada.');}
      break;
    }
    case'status':updateStatus(id,button.dataset.status);break;
    case'cancel':confirmStatus(id,'cancelled');break;
    case'reject':if(allowedTeam())confirmStatus(id,'rejected');break;
    case'reschedule':startBooking({appointmentId:id,manual:allowedTeam()});break;
    case'day':selectedDate=addDays(selectedDate,Number(button.dataset.offset));render();break;
    case'today':selectedDate=clinicNow().date;render();break;
    case'clear-filters':filters={search:'',status:'',doctor:'',date:''};render();break;
    case'patient-history':if(allowedTeam()){filters={search:patient(id).email,status:'',doctor:'',date:''};page='appointments';render();}break;
    case'block-modal':blockModal();break;
    case'remove-block':if(allowedTeam()){db=readDb();db.blocks=db.blocks.filter(b=>'b-'+b.id!==id);persist();render();toast('Bloqueio removido.');}break;
    case'export':exportCsv();break;
  }
});
document.addEventListener('input',event=>{
  const target=event.target;
  if(target.id==='filter-search'){filters.search=target.value;document.querySelector('#records-table').innerHTML=appointmentTable(recordsList());document.querySelector('#records-count').textContent=`${recordsList().length} agendamento(s) · Horário de Brasília`;}
  if(target.id==='patient-search')document.querySelector('#patients-table').innerHTML=patientsTable(target.value);
});
document.addEventListener('change',event=>{const target=event.target;
  if(['filter-status','filter-doctor','filter-date'].includes(target.id)){filters[target.id.replace('filter-','')]=target.value;document.querySelector('#records-table').innerHTML=appointmentTable(recordsList());document.querySelector('#records-count').textContent=`${recordsList().length} agendamento(s) · Horário de Brasília`;}
  if(target.id==='agenda-date'&&target.value){selectedDate=target.value;render();}
  if(target.id==='report-start'&&target.value){reportStart=target.value;if(reportStart>reportEnd)reportEnd=reportStart;render();}
  if(target.id==='report-end'&&target.value){reportEnd=target.value;if(reportEnd<reportStart)reportStart=reportEnd;render();}
});
document.addEventListener('submit',event=>{
  const form=event.target;event.preventDefault();const values=Object.fromEntries(new FormData(form));db=readDb();
  if(form.id==='patient-account'){
    try{const email=values.email.trim().toLowerCase(),name=values.name.trim(),phone=values.phone.trim();if(name.length<3||phone.replace(/\D/g,'').length<10)throw new Error('Informe nome e telefone válidos para a demonstração.');let p=db.patients.find(p=>p.email.toLowerCase()===email);if(!p){p={id:uid(),name,email,phone};db.patients.push(p);persist();}setRole('patient',{patientId:p.id});}catch(err){showError('form-error',err);}return;
  }
  if(form.id==='booking-form'&&booking){
    rememberBookingFields();const b=booking;
    try{
      if(!slots(db,b.doctorId,b.date,{excludeId:b.appointmentId}).includes(b.time))throw new Error('Este horário não está mais disponível. Volte e escolha outro.');
      let pid=b.patientId;
      if(!pid&&!b.manual){const name=values.name.trim(),email=values.email.trim().toLowerCase(),phone=values.phone.trim();if(name.length<3||phone.replace(/\D/g,'').length<10)throw new Error('Informe nome e telefone válidos para a demonstração.');let p=db.patients.find(p=>p.email.toLowerCase()===email);if(!p){p={id:uid(),name,email,phone};db.patients.push(p);}pid=p.id;}
      if(b.manual)pid=values.patientId;
      if(b.appointmentId){const existing=db.appointments.find(a=>a.id===b.appointmentId);if(!existing||!canAccess(existing)||!canManage(existing))throw new Error('Esta consulta não pode ser remarcada.');pid=existing.patientId;}
      const result=saveAppointment(db,{patientId:pid,doctorId:b.doctorId,date:b.date,time:b.time,notes:values.notes.trim(),excludeId:b.appointmentId});
      persist();if(!b.manual){session={role:'patient',patientId:pid};page='appointments';saveSession();}render();
      openModal(modalHead('Solicitação enviada')+`<div class="modal-body"><div class="success-view"><span class="success-icon">${icon('check')}</span><h3>Seu horário foi solicitado.</h3><p>A recepção precisa aprovar o agendamento. Você pode acompanhar a confirmação na área do paciente.</p></div><div style="margin-top:24px">${bookingSummary()}</div><div class="row spread"><small class="muted">Código ${result.id}</small>${badge('pending')}</div></div><div class="modal-footer"><small>Nenhuma mensagem externa foi enviada.</small><button class="btn" data-action="close">${b.manual?'Ver agendamentos':'Ver minhas consultas'} ${icon('arrow')}</button></div>`);booking=null;
    }catch(err){showError('booking-error',err);}return;
  }
  if(form.id==='block-form'&&allowedTeam()){
    try{if(values.date<clinicNow().date)throw new Error('Escolha uma data a partir de hoje.');addBlock(db,values);persist();closeModal();render();toast('Horário bloqueado. A disponibilidade já foi atualizada.');}catch(err){showError('form-error',err);}return;
  }
  if(form.id==='hours-form'&&session?.role==='admin'){
    try{
      const h=values;if(minutes(h.start)>=minutes(h.end)||minutes(h.start)>=minutes(h.saturdayEnd)||minutes(h.saturdayEnd)>minutes(h.end)||minutes(h.breakStart)>=minutes(h.breakEnd)||minutes(h.breakStart)<minutes(h.start)||minutes(h.breakEnd)>minutes(h.end))throw new Error('Revise a abertura, o fechamento e o intervalo.');
      const conflict=db.appointments.some(a=>['pending','confirmed'].includes(a.status)&&a.date>=clinicNow().date&&(minutes(a.time)<minutes(h.start)||minutes(a.time)+duration(a.doctorId)>minutes(weekday(a.date)===6?h.saturdayEnd:h.end)||overlap(minutes(a.time),minutes(a.time)+duration(a.doctorId),minutes(h.breakStart),minutes(h.breakEnd))));
      if(conflict)throw new Error('O novo funcionamento conflita com consultas existentes. Remarque ou cancele essas consultas antes de alterar.');
      db.hours=h;persist();render();toast('Horário de funcionamento atualizado.');
    }catch(err){showError('hours-error',err);}return;
  }
  if(form.id==='profile-form'&&session?.role==='patient'){
    try{const p=patient(session.patientId),email=values.email.trim().toLowerCase(),name=values.name.trim(),phone=values.phone.trim();if(db.patients.some(other=>other.id!==p.id&&other.email.toLowerCase()===email))throw new Error('Este e-mail já pertence a outro perfil da demonstração.');if(name.length<3||phone.replace(/\D/g,'').length<10)throw new Error('Informe nome e telefone válidos.');Object.assign(p,{name,email,phone});persist();render();toast('Dados do perfil atualizados.');}catch(err){showError('profile-error',err);}
  }
});
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
modal.addEventListener('cancel',()=>{booking=null;});
window.addEventListener('storage',event=>{if(event.key===KEY){db=readDb();render();if(booking)renderBooking();}});
persist();render();
